28	const BASE_PREMIUMS: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	  moonstone: 25,
35	};
36	
37	const PROCESSING_FEE = 5;
38	
39	const WHOLE_PERCENT = 100;
40	
41	/**
42	 * Surcharges multiply before dividing, so the arithmetic stays exact.
43	 * A 1.1 multiplier would not: floating-point `100 * 1.1` is
44	 * 110.00000000000001, which rounds up to 111 and yields a 116 G premium
45	 * instead of 115 G.
46	 */
47	const addSurcharge = (amount: number, surchargePercent: number): number =>
48	  (amount * (WHOLE_PERCENT + surchargePercent)) / WHOLE_PERCENT;
49	
50	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
51	
52	/** All rounding is in the MHPCO's favor — always up. */
53	const roundInMHPCOsFavor = Math.ceil;
54	
55	const BUILDING_BLOCK_SIZE = 3;
56	const BUILDING_BLOCK_PREMIUM = 60;
57	
58	/** Only items of one and the same kind group into a block. */
59	const areAllTheSameKind = ([first, ...rest]: InsuredItem[]): boolean =>
60	  first !== undefined && rest.every((item) => item.type === first.type);
61	
62	/**
63	 * How many flat-rate blocks this list forms. A mixed list forms none — only
64	 * alike items group — and so does any list too short to fill one block.
65	 */
66	const countCompleteBlocks = (items: InsuredItem[]): number =>
67	  areAllTheSameKind(items) ? Math.floor(items.length / BUILDING_BLOCK_SIZE) : 0;
68	
69	const CURSED_SURCHARGE_PERCENT = 50;
70	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
71	const HIGH_ENCHANTMENT_LEVEL = 5;
72	
73	/** Risk surcharges add to the base premium; they do not compound. */
74	const riskSurchargePercentFor = (item: InsuredItem): number =>
75	  (item.cursed ? CURSED_SURCHARGE_PERCENT : 0) +
76	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL
77	    ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT
78	    : 0);
79	
80	/** An item's list price with its own risk surcharges applied. */
81	const riskAdjustedPremiumFor = (item: InsuredItem): number =>
82	  addSurcharge(BASE_PREMIUMS[item.type], riskSurchargePercentFor(item));
83	
84	const sumIndividually = (items: InsuredItem[]): number =>
85	  items.reduce((sum, item) => sum + riskAdjustedPremiumFor(item), 0);
86	
87	/**
88	 * Prices an item list: alike items are grouped into building blocks sold at a
89	 * flat rate, and whatever is left over is the sum of its items' base premiums.
90	 */
91	const priceItems = (items: InsuredItem[]): number => {
92	  const blocks = countCompleteBlocks(items);
93	  const leftovers = items.slice(blocks * BUILDING_BLOCK_SIZE);
94	
95	  return blocks * BUILDING_BLOCK_PREMIUM + sumIndividually(leftovers);
96	};
97	
98	/**
99	 * The premium pipeline, in the order the spec states it: price the items,
100	 * apply surcharges, round, then add the processing fee last.
101	 */
102	const quotePremium = (step: Step): QuoteResult => {
103	  const basePremium = priceItems(step.items ?? []);
104	  const surcharged = addSurcharge(
105	    basePremium,
106	    FIRST_INSURANCE_SURCHARGE_PERCENT,
107	  );
108	
109	  return { premium: roundInMHPCOsFavor(surcharged) + PROCESSING_FEE };
110	};
111	
112	export const runScenario = (scenario: Scenario): ScenarioResults => ({
113	  results: scenario.steps.map(quotePremium),
114	});
